style:
:root { --ink: #1c2530; --muted: #5a6672; --line: #e1e6ec; --bg: #ffffff; --panel: #f6f8fa; --accent: #2f5d8a; --code-bg: #1f2630; --code-ink: #e8edf2; color-scheme: light; }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) { --ink: #e6edf3; --muted: #9fb0c0; --line: #2b3a4a; --bg: #0f1720; --panel: #172230; --accent: #8ab8e8; --code-bg: #0a1118; --code-ink: #e8edf2; color-scheme: dark; }
  }
  :root[data-theme="dark"] { --ink: #e6edf3; --muted: #9fb0c0; --line: #2b3a4a; --bg: #0f1720; --panel: #172230; --accent: #8ab8e8; --code-bg: #0a1118; --code-ink: #e8edf2; color-scheme: dark; }
  :root[data-theme="light"] { color-scheme: light; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: var(--ink); background: var(--bg); line-height: 1.62;
  }
  .wrap { max-width: 900px; margin: 0 auto; padding: 24px 24px 96px; }
  .topbar { display: flex; justify-content: flex-end; align-items: center; min-height: 40px; margin-bottom: 12px; }
  .theme-toggle { display: inline-flex; align-items: center; justify-content: center; min-width: 40px; min-height: 40px; padding: 4px 10px; font-size: 1.15rem; line-height: 1; color: var(--ink); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; cursor: pointer; }
  .theme-toggle[hidden] { display: none; }
  .theme-toggle:hover { border-color: var(--accent); }
  .table-scroll { max-width: 100%; overflow-x: auto; }
  .table-scroll > table { margin: 0; }
  .table-scroll { margin: 18px 0; }
  .theme-toggle:focus-visible, .table-scroll:focus-visible, a:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
  h1 { font-size: 1.9rem; line-height: 1.25; margin: 0 0 14px; padding-bottom: 18px; border-bottom: 3px solid var(--accent); }
  h2 { font-size: 1.3rem; margin: 44px 0 14px; padding-top: 14px; border-top: 1px solid var(--line); }
  h3 { font-size: 1.05rem; margin: 26px 0 10px; color: var(--accent); }
  p, li { margin: 10px 0; }
  a { color: var(--accent); text-decoration: none; }
  a:hover { text-decoration: underline; }
  code { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 1px 5px; font-size: 0.88em; }
  pre { background: var(--code-bg); color: var(--code-ink); border-radius: 8px; padding: 16px 18px; overflow-x: auto; line-height: 1.5; }
  pre code { background: none; border: 0; padding: 0; color: inherit; }
  table { border-collapse: collapse; width: 100%; margin: 18px 0; font-size: 0.92rem; }
  th, td { border: 1px solid var(--line); padding: 8px 11px; text-align: left; vertical-align: top; }
  th { background: var(--panel); }
  blockquote { margin: 18px 0; padding: 12px 18px; background: var(--panel); border-left: 4px solid var(--accent); border-radius: 6px; }
  blockquote p:first-child { margin-top: 0; }
  blockquote p:last-child { margin-bottom: 0; }
  hr { border: 0; border-top: 1px solid var(--line); margin: 36px 0; }
  .doc-meta { margin: 0 0 28px; padding: 14px 18px; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; }
  .doc-meta dl { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 12px 24px; margin: 0; }
  .doc-meta dt { color: var(--muted); font-size: 0.78rem; letter-spacing: 0.04em; text-transform: uppercase; }
  .doc-meta dd { margin: 2px 0 0; }
  .doc-meta__links { margin: 12px 0 0; font-size: 0.9rem; }
  footer.doc { margin-top: 56px; padding-top: 16px; border-top: 1px solid var(--line); color: var(--muted); font-size: 0.85rem; }
  @media (max-width: 600px) { .wrap { padding: 16px 16px 64px; } }

scripts.toggle:
(function () {
  var root = document.documentElement;
  var btn = document.getElementById('theme-toggle');
  if (!btn) return;
  var mq = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
  function effective() {
    var t = root.getAttribute('data-theme');
    if (t === 'light' || t === 'dark') return t;
    return mq && mq.matches ? 'dark' : 'light';
  }
  function sync() { btn.setAttribute('aria-pressed', String(effective() === 'dark')); }
  btn.hidden = false;
  sync();
  btn.addEventListener('click', function () {
    var next = effective() === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    try { localStorage.setItem('portfolio-docs-theme', next); } catch (e) {}
    sync();
  });
  if (mq && mq.addEventListener) mq.addEventListener('change', sync);
})();
